// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.json;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.junit.jupiter.api.Test;

/**
 * Edge cases for {@code jsonf:jsonValue}, {@code jsonf:jsonQuery} and {@code jsonf:jsonExists}.
 */
class JsonValueQueryExistsEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static Literal json(String s) {
		return VF.createLiteral(s, CoreDatatype.RDF.JSON);
	}

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Value value(String document, String path) {
		return new JsonValue().evaluate(VF, json(document), str(path));
	}

	private static Literal query(String document, String path) {
		return new JsonQuery().evaluate(VF, json(document), str(path));
	}

	private static Literal exists(String document, String path) {
		return new JsonExists().evaluate(VF, json(document), str(path));
	}

	// ------------------------------------------------------------------ jsonValue

	@Test
	void jsonValueMapsScalarsToTypedLiterals() {
		String document = "{\"s\":\"abc\",\"i\":42,\"n\":-7,\"d\":2.50,\"e\":1e2,\"t\":true,\"f\":false}";
		Literal s = (Literal) value(document, "$.s");
		assertThat(s.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.STRING);
		assertThat(s.getLabel()).isEqualTo("abc");
		Literal i = (Literal) value(document, "$.i");
		assertThat(i.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
		assertThat(i.integerValue()).isEqualTo(BigInteger.valueOf(42));
		assertThat(value(document, "$.n")).isEqualTo(VF.createLiteral(BigInteger.valueOf(-7)));
		Literal d = (Literal) value(document, "$.d");
		assertThat(d.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL);
		assertThat(d.getLabel()).isEqualTo("2.50");
		// pins current behaviour: an exponent number becomes xsd:double with RDF4J's Double.toString lexical form
		Literal e = (Literal) value(document, "$.e");
		assertThat(e.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.DOUBLE);
		assertThat(e.getLabel()).isEqualTo("100.0");
		assertThat(value(document, "$.t")).isEqualTo(BooleanLiteral.TRUE);
		assertThat(value(document, "$.f")).isEqualTo(BooleanLiteral.FALSE);
		assertThat(((Literal) value(document, "$.f")).getCoreDatatype()).isEqualTo(CoreDatatype.XSD.BOOLEAN);
	}

	@Test
	void jsonValueOfNullIsAnEvaluationError() {
		// pins current behaviour: JSON null has no RDF term, so jsonValue raises an error (BIND leaves it unbound)
		assertThatThrownBy(() -> value("{\"a\":null}", "$.a"))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("null");
		assertThatThrownBy(() -> value("[null]", "$[0]")).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> value("null", "$")).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void jsonValueOfObjectArrayOrSeveralMatchesIsAnEvaluationError() {
		String document = "{\"o\":{\"k\":1},\"l\":[1,2],\"e\":{},\"ea\":[],\"x\":[{\"y\":1},{\"y\":2}],"
				+ "\"one\":[{\"y\":3}]}";
		for (String path : List.of("$.o", "$.l", "$.e", "$.ea", "$")) {
			assertThatThrownBy(() -> value(document, path))
					.as(path)
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining("selects an object or array");
		}
		for (String path : List.of("$.l[*]", "$.x[*].y", "$..y", "$..*")) {
			assertThatThrownBy(() -> value(document, path))
					.as(path)
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining("more than one value");
		}
		// an indefinite path that happens to select exactly one scalar is fine
		assertThat(value(document, "$.one[*].y")).isEqualTo(VF.createLiteral(BigInteger.valueOf(3)));
		assertThat(value(document, "$.o.*")).isEqualTo(VF.createLiteral(BigInteger.ONE));
	}

	@Test
	void jsonValueDecodesTermObjects() {
		String document = "{\"lang\":{\"@value\":\"x\",\"@language\":\"en\"},"
				+ "\"dir\":{\"@value\":\"x\",\"@language\":\"ar\",\"@direction\":\"rtl\"},"
				+ "\"iri\":{\"@id\":\"http://example.org/a\"},\"bnode\":{\"@id\":\"_:b1\"},"
				+ "\"byte\":{\"@value\":\"1\",\"@type\":\"http://www.w3.org/2001/XMLSchema#byte\"},"
				+ "\"date\":{\"@value\":\"2024-02-29\",\"@type\":\"http://www.w3.org/2001/XMLSchema#date\"},"
				+ "\"notTerm\":{\"@value\":\"x\",\"other\":1},\"idPlus\":{\"@id\":\"urn:a\",\"x\":1}}";
		assertThat(value(document, "$.lang")).isEqualTo(VF.createLiteral("x", "en"));
		assertThat(value(document, "$.dir")).isEqualTo(VF.createLiteral("x", "ar", Literal.BaseDirection.RTL));
		assertThat(value(document, "$.iri")).isEqualTo(VF.createIRI("http://example.org/a"));
		assertThat(value(document, "$.bnode")).isEqualTo(VF.createBNode("b1"));
		assertThat(value(document, "$.byte")).isEqualTo(VF.createLiteral("1", XSD.BYTE));
		assertThat(((Literal) value(document, "$.byte")).getCoreDatatype()).isEqualTo(CoreDatatype.XSD.BYTE);
		assertThat(value(document, "$.date")).isEqualTo(VF.createLiteral("2024-02-29", XSD.DATE));
		// objects that merely contain @value / @id among other members are ordinary objects, not terms
		assertThatThrownBy(() -> value(document, "$.notTerm"))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("selects an object or array");
		assertThatThrownBy(() -> value(document, "$.idPlus"))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("selects an object or array");
	}

	@Test
	void jsonValueOfHugeExponentNumberIsAnErrorNotAnExpansion() {
		for (String number : List.of("1e400", "-1e400", "1e-400", "2.5E+999", "1e309")) {
			assertThatThrownBy(() -> value("[" + number + "]", "$[0]"))
					.as(number)
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining("exponent number outside the finite, nonzero double range");
		}
		// exponent numbers inside the double range and exponent zeros are plain doubles
		assertThat(value("[1e308]", "$[0]")).isEqualTo(VF.createLiteral(1e308));
		assertThat(value("[0e5]", "$[0]")).isEqualTo(VF.createLiteral(0.0));
		assertThat(value("[-0e5]", "$[0]")).isEqualTo(VF.createLiteral(-0.0));
	}

	// ------------------------------------------------------------------ jsonQuery

	@Test
	void jsonQueryZeroOneAndSeveralMatches() {
		String document = "{\"a\":{\"k\":1},\"l\":[{\"k\":2},{\"k\":3}]}";
		// pins current behaviour: zero matches is an evaluation error (BIND leaves the variable unbound)
		assertThatThrownBy(() -> query(document, "$.missing"))
				.isInstanceOf(ValueExprEvaluationException.class)
				.hasMessageContaining("selects no value");
		assertThatThrownBy(() -> query(document, "$.l[*].missing")).isInstanceOf(ValueExprEvaluationException.class);
		assertThat(query(document, "$.a")).isEqualTo(json("{\"k\":1}"));
		assertThat(query(document, "$.l[0]")).isEqualTo(json("{\"k\":2}"));
		assertThat(query(document, "$.l[*].k")).isEqualTo(json("[2,3]"));
		assertThat(query(document, "$..k")).isEqualTo(json("[1,2,3]"));
		// a single match that is itself an array is returned as that array, not wrapped again
		assertThat(query(document, "$.l")).isEqualTo(json("[{\"k\":2},{\"k\":3}]"));
		// but a wildcard selecting one array element that is an array keeps its own brackets only
		assertThat(query("[[1,2]]", "$[*]")).isEqualTo(json("[1,2]"));
	}

	@Test
	void jsonQueryScalarResultIsStillRdfJson() {
		String document = "{\"s\":\"abc\",\"n\":1,\"d\":1.5,\"z\":null,\"t\":true,\"q\":\"he said \\\"hi\\\"\"}";
		for (String[] expected : List.of(new String[] { "$.s", "\"abc\"" }, new String[] { "$.n", "1" },
				new String[] { "$.d", "1.5" }, new String[] { "$.z", "null" }, new String[] { "$.t", "true" },
				new String[] { "$.q", "\"he said \\\"hi\\\"\"" })) {
			Literal result = query(document, expected[0]);
			assertThat(result.getCoreDatatype()).as(expected[0]).isEqualTo(CoreDatatype.RDF.JSON);
			assertThat(result.getLabel()).as(expected[0]).isEqualTo(expected[1]);
		}
		assertThat(query("\"root\"", "$")).isEqualTo(json("\"root\""));
	}

	@Test
	void jsonQueryOutputIsCanonicalWithKeyOrderPreserved() {
		assertThat(query(" { \"b\" : 1 ,\n\t \"a\" : [ 1 , 2 , { \"c\" : [ ] } ] , \"d\" : { } } ", "$"))
				.isEqualTo(json("{\"b\":1,\"a\":[1,2,{\"c\":[]}],\"d\":{}}"));
		// escapes: \u0041 is decoded to A, control characters and quotes are re-escaped, non-ASCII stays literal
		assertThat(query("{\"k\":\"a\\u0041\\n\\\"q\\\"\\t\\u00e9\\u0001\\/\"}", "$").getLabel())
				.isEqualTo("{\"k\":\"aA\\n\\\"q\\\"\\t\u00e9\\u0001/\"}");
		// key order of a nested object survives, including after a wildcard
		assertThat(query("{\"z\":{\"y\":1,\"x\":2},\"w\":0}", "$.z")).isEqualTo(json("{\"y\":1,\"x\":2}"));
		assertThat(query("{\"z\":{\"y\":1,\"x\":2},\"w\":0}", "$.*")).isEqualTo(json("[{\"y\":1,\"x\":2},0]"));
		// re-querying the output gives the same document (idempotent canonical form)
		Literal once = query("{ \"b\" : [1.10, 2] }", "$");
		assertThat(new JsonQuery().evaluate(VF, once, str("$"))).isEqualTo(once).isEqualTo(json("{\"b\":[1.10,2]}"));
	}

	// ------------------------------------------------------------------ jsonExists

	@Test
	void jsonExistsNullValuedKeyIsTrueAndAbsentIsFalse() {
		String document = "{\"a\":null,\"b\":{\"c\":null},\"l\":[null]}";
		assertThat(exists(document, "$.a")).isEqualTo(BooleanLiteral.TRUE);
		assertThat(exists(document, "$.b.c")).isEqualTo(BooleanLiteral.TRUE);
		assertThat(exists(document, "$.l[0]")).isEqualTo(BooleanLiteral.TRUE);
		assertThat(exists(document, "$")).isEqualTo(BooleanLiteral.TRUE);
		assertThat(exists(document, "$.x")).isEqualTo(BooleanLiteral.FALSE);
		assertThat(exists(document, "$.a.x")).isEqualTo(BooleanLiteral.FALSE);
		assertThat(exists(document, "$.l[1]")).isEqualTo(BooleanLiteral.FALSE);
		assertThat(exists(document, "$..missing")).isEqualTo(BooleanLiteral.FALSE);
		assertThat(exists("[]", "$[*]")).isEqualTo(BooleanLiteral.FALSE);
		assertThat(exists("{}", "$.*")).isEqualTo(BooleanLiteral.FALSE);
	}

	@Test
	void jsonExistsPathErrorIsAnErrorNotFalse() {
		// pins current behaviour: a malformed path raises an evaluation error (false in FILTER, unbound in BIND)
		for (String path : List.of("$[", "$.", "$.a[?(@)]")) {
			assertThatThrownBy(() -> exists("{\"a\":1}", path))
					.as(path)
					.isInstanceOf(ValueExprEvaluationException.class)
					.hasMessageContaining("Invalid JSON path");
		}
	}

	@Test
	void jsonExistsOnInvalidJsonIsAnErrorNotFalse() {
		assertThatThrownBy(() -> exists("nope", "$.a")).isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonExists().evaluate(VF, VF.createLiteral(1), str("$")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new JsonExists().evaluate(VF, VF.createIRI("urn:x"), str("$")))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void jsonValueAndJsonQueryAgreeOnDecimalPrecision() {
		// a decimal keeps its scale through both functions
		assertThat(value("[10.00]", "$[0]")).isEqualTo(VF.createLiteral(new BigDecimal("10.00")));
		assertThat(query("[10.00]", "$[0]")).isEqualTo(json("10.00"));
		assertThat(value("[123456789012345678901234567890]", "$[0]"))
				.isEqualTo(VF.createLiteral(new BigInteger("123456789012345678901234567890")));
	}
}
